/*
 * A021352  Decimal expansion of 1/348.
 * https://oeis.org/A021352
 *
 * Offset:    0    (a(0) is the first term)
 * Keywords:  nonn, cons, easy
 * Formula:   a(n) = the n‑th digit after the decimal point in the expansion
 *            of 1/348 (decimal expansion of 1/348). The sequence can be
 *            generated by the standard long division algorithm: start with
 *            remainder 1 and repeatedly multiply by 10, take the quotient
 *            digit and update the remainder
 * Range:     u8 n <= 0, u16 n <= 98, u32 n <= 98, u64 n <= 98, u128 n <= 98,
 *            big any n
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

#include <stdint.h>

seq_t a(idx_t n)
{
    /* Since the remainder never exceeds 347*10, a 64‑bit type is enough for
       the intermediate calculations.  We use seq_t itself for interoperability
       with the caller’s integer size. */
    seq_t rem = (seq_t)1;   /* remainder of the fraction at each step */
    seq_t digit = 0;
    idx_t i = 0;

    /* Compute the digits one by one until we reach position n.
       For the case n = UINT64_MAX this loop would be impractical,
       but the problem context limits n to reasonable sizes (≤ ~10000). */
    for ( ; i <= n; ++i )
    {
        rem *= 10;          /* shift the fraction one digit to the left */
        digit = rem / (seq_t)348;
        rem   = rem % (seq_t)348;
    }
    return digit;
}
